using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows.Forms;using System.Windows.Media.Media3D;
namespace GearLab {
 public sealed partial class RobotDesignerForm {
  readonly CADKernel bodyKernel=new CADKernel();readonly Timer bodyDelay=new Timer();readonly Dictionary<string,string> failedBodies=new Dictionary<string,string>();bool bodyBusy;readonly RobotWebViewport robotWeb=new RobotWebViewport();bool webFit=true;
  void InitializeProceduralWorkspace(SplitContainer content){content.Panel1.Controls.Add(robotWeb);robotWeb.BringToFront();robotWeb.ReadyChanged+=()=>{if(robotWeb.Ready){host.Visible=false;RenderWebRobot();}else{robotWeb.Visible=false;host.Visible=true;}};robotWeb.Message+=HandleWebRobot;bodyDelay.Interval=700;bodyDelay.Tick+=(s,e)=>{bodyDelay.Stop();RegenerateBodies();};bodyKernel.Progress+=message=>{if(!disposed&&IsHandleCreated)BeginInvoke(new Action(()=>summary.Text=message));};}
  void OpenProceduralExample(){string basePath=Path.GetDirectoryName(Application.ExecutablePath);string file=new[]{Path.Combine(basePath,"examples","Procedural_180_NEMA17.robot.json"),Path.Combine(Path.GetDirectoryName(basePath),"examples","Procedural_180_NEMA17.robot.json")}.FirstOrDefault(File.Exists);if(file!=null){Replace(RobotDocument.Parse(File.ReadAllText(file)),null);SetStage(2);return;}var doc=new RobotDocument{Name="Процедурный пример · NEMA 17 / 180 мм"};var j=doc.Add(null);j.Mode=RobotJointMode.Вращение_Z;j.EndX=180;j.OffsetZ=100;j.Reduction=12;j.Payload=.5;j.BodyGenerator=new ProceduralBodySettings();Replace(doc,null);SetStage(2);}
  internal void OpenProceduralBody(){var joint=Joint;if(joint==null)return;Stop();string id=joint.Id;var source=Document.Clone();WorkspaceHost.Open(this,new ProceduralBodyForm(source,id,(settings,result)=>{var live=Document.Find(id);if(live==null){MessageBox.Show(this,"Звено удалено.");return false;}if(ProceduralBodySpec.Fingerprint(Document,live,settings)!=result.Fingerprint){MessageBox.Show(this,"Скелет, механика или нагрузка изменились. Откройте генератор заново для текущего звена.");return false;}bool accepted=Mutate(()=>{live.BodyGenerator=settings;live.GeneratedBody=result;});if(accepted){view.SelectedIndex=1;webFit=true;RenderWebRobot();}return accepted;}));}
  void QueueBodyRegeneration(){if(disposed)return;bodyDelay.Stop();bodyDelay.Start();}
  internal RobotWebViewport WebScene{get{return robotWeb;}}
  internal bool ProceduralBusy{get{return bodyBusy;}}
  async void RegenerateBodies(){if(bodyBusy||disposed)return;var joint=Document.Ordered().AsEnumerable().Reverse().FirstOrDefault(j=>j.BodyGenerator!=null&&j.BodyGenerator.Enabled&&j.BodyGenerator.AutoRegenerate&&(j.GeneratedBody==null||j.GeneratedBody.Fingerprint!=ProceduralBodySpec.Fingerprint(Document,j,j.BodyGenerator))&&(!failedBodies.ContainsKey(j.Id)||failedBodies[j.Id]!=ProceduralBodySpec.Fingerprint(Document,j,j.BodyGenerator)));if(joint==null)return;var source=Document.Clone();string id=joint.Id,signature=ProceduralBodySpec.Fingerprint(source,source.Find(joint.Id),joint.BodyGenerator);bodyBusy=true;summary.Text=joint.Name+" · локальное перестроение корпуса…";try{var generated=await Task.Factory.StartNew(()=>ProceduralBodySpec.Generate(bodyKernel,source,source.Find(id),source.Find(id).BodyGenerator));if(disposed)return;var live=Document.Find(id);if(live==null||live.BodyGenerator==null||signature!=ProceduralBodySpec.Fingerprint(Document,live,live.BodyGenerator)){return;}if(!generated.Result.GeometryValid){failedBodies[id]=signature;notes.AppendText("\r\n"+live.Name+": новое построение не применено; сохранён предыдущий корпус. "+string.Join("; ",generated.Result.Issues.Where(i=>i.Status=="error").Select(i=>i.Message).Take(3)));return;}live.GeneratedBody=generated;failedBodies.Remove(id);Rebuild();}catch(Exception ex){if(!disposed){failedBodies[id]=signature;notes.AppendText("\r\nКорпус "+joint.Name+": "+ex.GetBaseException().Message+". Предыдущая геометрия сохранена.");}}finally{bodyBusy=false;if(!disposed){bodyDelay.Stop();bodyDelay.Start();}}}
  void RenderWebRobot(){if(!robotWeb.Ready||Build==null)return;robotWeb.Clear();foreach(var e in Build.Entries.Values.Where(x=>!x.Guide)){var mesh=e.Part.MeshOverride??PrintExport.Mesh(e.Part);robotWeb.Part(e.Id,e.Part.Label,mesh,Build.Pose(e.Id,phase,playing||Math.Abs(phase)>1e-9),e.Part.Color,true,e.Category);}UpdateWebPose();FilterWebRobot();robotWeb.Select(selectedPart??(selectedJoint==null?null:selectedJoint+"_end_guide"));if(webFit){robotWeb.Send(new{type="preset",view=Document.Joints.Any(j=>j.BodyGenerator!=null&&j.BodyGenerator.ReferenceDesign)?"REFERENCE":"ISO"});webFit=false;}}
  void FilterWebRobot(){if(!robotWeb.Ready||Build==null)return;robotWeb.Send(new{type="visibility",hidden=Build.Entries.Values.Where(e=>e.Guide||(view.SelectedIndex==0?e.Category!="Мотор":view.SelectedIndex==2?!e.Printable:false)).Select(e=>e.Id).ToArray()});}
  void UpdateWebPose(){SyncJointControllers();if(!robotWeb.Ready||Build==null)return;robotWeb.Send(new{type="poses",parts=Build.Entries.Values.Where(e=>!e.Guide).Select(e=>new{id=e.Id,matrix=RobotWebViewport.Matrix(Build.Pose(e.Id,phase,playing||Math.Abs(phase)>1e-9))}).ToArray()});var poses=RobotKinematics.Evaluate(Document,phase,playing||Math.Abs(phase)>1e-9);robotWeb.Send(new{type="bones",bones=(stage==0||view.SelectedIndex==0||move!=null&&move.Checked?Document.Joints:Enumerable.Empty<RobotJoint>()).Select(j=>new{id=j.Id,label=j.Name+" · "+Engine.F(j.Length)+" мм",origin=new[]{poses[j.Id].Origin.X,poses[j.Id].Origin.Y,poses[j.Id].Origin.Z},tip=new[]{poses[j.Id].Tip.X,poses[j.Id].Tip.Y,poses[j.Id].Tip.Z},selected=j.Id==selectedJoint}).ToArray()});SendJointController();}
  void HandleWebRobot(Dictionary<string,object> data){try{string type=Convert.ToString(data["type"]);if(type=="controllerMode"){OpenJointControllers();}else if(type.StartsWith("joint",StringComparison.Ordinal)){HandleJointControlMessage(data);}else if(type=="moveMode"){move.Checked=Convert.ToBoolean(data["enabled"]);if(move.Checked){Stop();CapturePose();}UpdateWebPose();}else if(type=="select"){string id=data.ContainsKey("id")?Convert.ToString(data["id"]):null;RobotCadEntry e;if(id!=null&&Build.Entries.TryGetValue(id,out e))Select(e.JointId,e.Guide?null:id);else if(Document.Find(id)!=null)Select(id,null);}else if(type=="boneMoved"||type=="partMoved"){Stop();CapturePose();string id=Convert.ToString(data["id"]);var delta=RobotWebViewport.Numbers(data["delta"],3);CommitDrag(id,new Vector3D(delta[0],delta[1],delta[2]));UpdateWebPose();}}catch(Exception ex){notes.AppendText("\r\nСцена: "+ex.Message);RenderWebRobot();}}
 }
}
